#!/usr/bin/env python3
"""Regenerate public RFC7919 Montgomery constants, avoiding expensive Rust const evaluation."""
from pathlib import Path
import sys
MODULI = {2048: '', 3072: ''}

def source():
    lines = ["//! RFC7919 public parameters. Generated by generate_params.py; no runtime initialization.",
             "use crypto_bigint::{U2048, U3072, Limb, modular::constant_mod::ResidueParams};", ""]
    for bits, encoded in MODULI.items():
        modulus = int(encoded, 16)
        assert modulus.bit_length() == bits
        assert all((-pow(modulus, -1, 1 << word)) % (1 << word) == 1 for word in (32, 64))
        lines += ["#[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]",
                  f"pub struct Modulus{bits};", f"impl ResidueParams<{{ U{bits}::LIMBS }}> for Modulus{bits} {{",
                  f"    const LIMBS: usize = U{bits}::LIMBS;"]
        constants = {"MODULUS": modulus, "R": pow(2, bits, modulus), "R2": pow(2, 2*bits, modulus), "R3": pow(2, 3*bits, modulus)}
        for name, value in constants.items():
            lines.append(f'    const {name}: U{bits} = U{bits}::from_be_hex("{value:0{bits//4}x}");')
        lines += ["    // Both RFC moduli end in all-one 32/64-bit limbs: -p^-1 = 1.",
                  "    const MOD_NEG_INV: Limb = Limb(1);", "}", ""]
    return "\n".join(lines)

if __name__ == '__main__':
    output = Path(__file__).with_name('params.rs')
    generated = source()
    if sys.argv[1:] == ['--check']:
        assert output.read_text() == generated, 'Montgomery constants differ'
    elif not sys.argv[1:]:
        output.write_text(generated)
    else:
        raise SystemExit('usage: generate_params.py [--check]')
